-- Synthetic local fixture only. Never submit this file to the managed database.
CREATE ROLE anon; CREATE ROLE authenticated; CREATE ROLE service_role BYPASSRLS;
CREATE SCHEMA auth;
CREATE TABLE auth.users(id uuid PRIMARY KEY,banned_until timestamptz);
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql AS $$ SELECT NULLIF(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
CREATE TABLE public.profiles(id uuid PRIMARY KEY REFERENCES auth.users ON DELETE CASCADE,full_name text NOT NULL,employee_no text NOT NULL,active boolean NOT NULL DEFAULT true);
CREATE TABLE public.user_roles(user_id uuid REFERENCES auth.users ON DELETE CASCADE,role text);
CREATE TABLE public.profile_stations(user_id uuid REFERENCES auth.users ON DELETE CASCADE);
CREATE FUNCTION public.has_role(_user_id uuid,_role text) RETURNS boolean LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE TABLE public.audit_events(actor_id uuid,event_type text,entity_table text,entity_id uuid,details jsonb);
CREATE TABLE public.deleted_items(deleted_by uuid,restored_by uuid,row_data jsonb);
CREATE TABLE public.app_installation(initialized_by uuid);
CREATE TABLE public.checklist_entries(operator_id uuid,operator_name text);
CREATE TABLE public.checklist_reports(operator_id uuid,operator_name text);
CREATE TABLE public.defeat_records(created_by uuid);
CREATE TABLE public.equipment_availability_entries(operator_id uuid REFERENCES auth.users ON DELETE SET NULL,operator_name text,supervisor_id uuid,supervisor_name text);
CREATE TABLE public.fire_pump_tests(created_by uuid,operator_id uuid,operator_name text);
CREATE TABLE public.generator_tests(created_by uuid,operator_id uuid,operator_name text);
CREATE TABLE public.incident_attachments(uploaded_by uuid REFERENCES auth.users ON DELETE SET NULL);
CREATE TABLE public.incidents(reported_by uuid REFERENCES auth.users ON DELETE SET NULL,reporter_name text);
CREATE TABLE public.notifications(user_id uuid);
CREATE TABLE public.reading_entries(operator_id uuid REFERENCES auth.users ON DELETE SET NULL,operator_name text);
CREATE TABLE public.scada_samples(recorded_by uuid);
CREATE TABLE public.shift_reports(operator_id uuid REFERENCES auth.users ON DELETE SET NULL,reported_by text);
CREATE TABLE public.station_messages(author_id uuid,author_name text,target_user_ids uuid[]);
CREATE TABLE public.station_notes(author_id uuid REFERENCES auth.users,author_name text);
CREATE TABLE public.supervisor_routines(created_by uuid,supervisor_id uuid,supervisor_name text);
